mapper.select:
SELECT * FROM sys_user

ORDER BY id
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE sys_user
nickname = #{nickname}, status = #{status},
WHERE id = #{id}

mapper.select:
SELECT DISTINCT u.id AS "id", u.username AS "username", u.nickname AS "nickname" FROM sys_user u
JOIN sys_user_role ur ON ur.user_id = u.id JOIN sys_role_menu rm ON rm.role_id = ur.role_id JOIN sys_menu m ON m.id = rm.menu_id AND m.perms = #{perm}
WHERE u.status = '0' ORDER BY u.id
